import{createRequire}from'node:module';import{resolve}from'node:path';import{pathToFileURL}from'node:url';import{mkdir,writeFile}from'node:fs/promises';
const require=createRequire(import.meta.url),{chromium}=require('C:/Users/genki/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright-core');const evidence=resolve('../../outputs/verification-v36-early-result-facts-v1');await mkdir(evidence);
const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});
try{
 const page=await browser.newPage({viewport:{width:1200,height:860}});await page.goto(pathToFileURL(resolve('../../outputs/ばせぼーるlv35_TBD_vs_LAD_俯瞰と左右スイング修正版.html')).href);await page.evaluate(()=>document.fonts.ready);
 const report=await page.evaluate(async()=>{
  const observations=[],found={},api=window.liveMatchPlayback,data=JSON.parse(document.getElementById('match-data').textContent);
  function describe(record,index){
   const field=record.play.field,rule=field?.ruleFacts,over=rule?.overFence,catchFact=rule?.flyCatch,at=over?.tick??catchFact?.secureCatchTick;
   const before=at===undefined?null:record.frames.filter(f=>f.tick<at).at(-1),after=at===undefined?null:record.frames.find(f=>f.tick>=at);
   const frame=f=>f?{tick:f.tick,phase:f.phase,ballKind:f.ballKind,homeRunConfirmed:f.homeRunConfirmed??false,possessedBy:f.possessedBy,fairKnown:f.fairKnown}:null;
   return{index,pitch:index+1,name:data.players[record.batterPlayerId].name,batterId:record.batterPlayerId,beforeMatch:record.beforeMatch,classification:record.play.classification,
    overFence:over??null,flyCatch:catchFact??null,firstGroundContactTick:rule?.firstGroundContactTick??null,territory:rule?.territory??null,
    homeTouches:rule?.runnerTouches.filter(f=>f.base===4)??[],endedAtTick:record.play.rules.endedAtTick,outcomes:record.play.rules.outcomes,
    eventBefore:frame(before),eventAfter:frame(after),firstHomeRunFrame:frame(record.frames.find(f=>f.homeRunConfirmed)),
    eventToOfficialSeconds:at===undefined?null:(record.play.rules.endedAtTick-at)/1e6,
    scoredRunnerIds:record.play.rules.scoredRunnerIds,scoreAfter:record.match.score,
    relevantEvents:record.events.filter(e=>['over_fence','catch_secured','runner_out','runner_base_touch','territory_determined','pitch_adjudicated'].includes(e.kind))};
  }
  for(let i=0;i<60;i++){
   document.getElementById('next-pitch').click();api.stop();const s=api.inspect();if(s.error)throw Error(s.error);
   const record=s.lastResult,name=data.players[record.batterPlayerId].name;observations.push({index:i,name,inning:record.beforeMatch.inning,half:record.beforeMatch.half,classification:record.play.classification});
   if(name==='FANZAWA'&&record.beforeMatch.inning===1&&record.play.classification==='home_run')found.fanzawa=describe(record,i);
   if(!found.fly&&record.play.classification==='fly_out')found.fly=describe(record,i);
   if(found.fanzawa&&found.fly)break;
   await new Promise(r=>setTimeout(r,0));
  }
  const s=api.inspect();return{defaultSeed:document.getElementById('match-seed').value,generated:s.generatedPitches,found,observations,sourceAuthority:s.authority};
 });
 await writeFile(resolve(evidence,'early-result-facts.json'),JSON.stringify(report,null,2)+'\n');
 console.log(JSON.stringify({defaultSeed:report.defaultSeed,generated:report.generated,found:Object.fromEntries(Object.entries(report.found).map(([key,r])=>[key,{pitch:r.pitch,name:r.name,classification:r.classification,overFence:r.overFence,flyCatch:r.flyCatch,firstHRFrame:r.firstHomeRunFrame,homes:r.homeTouches,endedAtTick:r.endedAtTick,delay:r.eventToOfficialSeconds,outcomes:r.outcomes}])),evidence},null,2));await page.close();
}finally{await browser.close();}
